{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C04","C17","C19","C22","C23","C58","C61","C63","C65","C66","C67","C68","C74","C75","C78","C79"],
  "contradictory_card_ids": ["C46","C50","C54"],
  "prediction_basis_card_ids": ["C04","C17","C23","C58","C61","C65","C66","C67","C68","C74","C78","C75","C79"],
  "claims": [
    {
      "claim": "L1 direct human outcomes for structurally similar large lipophilic molecules are low: lopinavir has poor or very low oral bioavailability and SRT2104 has absolute F of 13.8 percent.",
      "card_ids": ["C04","C19","C22","C17","C23"]
    },
    {
      "claim": "L4 solubility records for the HIV protease inhibitor class show very low aqueous solubility: lopinavir 2.9 to 3.7 micrograms per mL, atazanavir 0.81 to 1.23 micrograms per mL, darunavir 11 to 31 percent unformulated release, and saquinavir coarse powder 20 percent.",
      "card_ids": ["C58","C61","C63","C59","C65","C66","C67","C68"]
    },
    {
      "claim": "The query is neutral at physiological pH, has logD 5.91, molecular weight 720.96, and high TPSA, matching the poor solubility profile of the non-basic protease inhibitor class.",
      "card_ids": ["C58","C61","C63","C65","C66"]
    },
    {
      "claim": "L5 gut-wall records show cobicistat, which shares the isopropyl-thiazole urea and thiazole carbamate scaffold with the query, is a Pgp and BCRP substrate, indicating efflux-mediated presystemic loss.",
      "card_ids": ["C74","C78"]
    },
    {
      "claim": "Lopinavir requires solid lipid nanoparticles to enhance oral bioavailability and saquinavir has low Caco-2 permeability of 2.25 times 10 to the minus 6 cm per second, supporting low absorption for this class.",
      "card_ids": ["C75","C79"]
    },
    {
      "claim": "Rovatirelin exposure increases when intestinal CYP3A4 and P-gp are inhibited, showing that gut-wall metabolism and efflux can limit oral exposure, though this is not a direct query measurement.",
      "card_ids": ["C69"]
    },
    {
      "claim": "L3 cobicistat exposure records show substantial plasma AUC and Cmax but lack an IV comparator, and cobicistat has a basic morpholine absent in the query, so they do not establish F at or above 20 percent for the query.",
      "card_ids": ["C46","C50","C54"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C69","C74","C75","C78","C79"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query is visible.",
    "L5 records are mechanistic gut-wall assays, not systemic F measurements for the query.",
    "Cobicistat exposure records lack an IV comparator, so cobicistat F is not directly established.",
    "Query-specific fasted-state solubility, permeability, and efflux are not experimentally measured."
  ],
  "decision_summary": "L5 gut-wall evidence supports the low prediction: cobicistat, sharing the query's isopropyl-thiazole urea and thiazole carbamate scaffold, is a Pgp and BCRP substrate; lopinavir requires lipid nanoparticles to improve oral bioavailability; and saquinavir has low Caco-2 permeability. Combined with L1 direct low outcomes for similar molecules and L4 poor solubility, the query's neutral, highly lipophilic, large profile supports F below 20 percent. Cobicistat exposure records lack an IV comparator and do not overturn this. Prediction remains low with moderate confidence."
}

